<span class="line"><span style="color:#ABB2BF;">            ?? </span><span style="color:#C678DD;">throw</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">InvalidOperationException</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;File content state not found&quot;</span><span style="color:#ABB2BF;">);</span></span>
