<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">WorkflowBuilder</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">startExecutor</span><span style="color:#ABB2BF;">: </span><span style="color:#E06C75;">executorA</span><span style="color:#ABB2BF;">)</span></span>
