<span class="line"><span style="color:#C678DD;">    private</span><span style="color:#E5C07B;"> List</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#C678DD;">string</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#E06C75;">_messages</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> new();</span></span>
